fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Given the preconditions, both arrays have the same length
    debug_assert_eq!(arr1.len(), arr2.len());

    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a % b)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let a: Vec<u32> = vec![];
        let b: Vec<u32> = vec![];
        assert_eq!(element_wise_module(&a, &b), vec![]);
    }

    #[test]
    fn test_simple() {
        let a = vec![10, 20, 30, 40];
        let b = vec![3, 7, 5, 8];
        // 10%3=1, 20%7=6, 30%5=0, 40%8=0
        assert_eq!(element_wise_module(&a, &b), vec![1, 6, 0, 0]);
    }

    #[test]
    fn test_various() {
        let a = vec![0, 1, 2, 3, 4, u32::MAX];
        let b = vec![1, 1, 2, 4, 3, u32::MAX];
        assert_eq!(
            element_wise_module(&a, &b),
            vec![0, 0, 0, 3 % 4, 4 % 3, u32::MAX % u32::MAX]
        );
    }
}